# Pattern for Store.GetUser call (not mysql DB, not API service)
call_pattern = re.compile(
    r'(?:(?:[\w.]+\.)?(?:Store|store|stores|ts)\.GetUser|s\.GetUser)\s*\(\s*ctx'
)

# Also match s.GetUser in store package where s is *Store
store_pkg_pattern = re.compile(r's\.GetUser\s*\(\s*ctx')

skip_files = set()

results = []  # (filepath, line, line_content, func_name)

def find_func_name(lines, line_idx):
    """Find enclosing func name by scanning backwards."""
    for i in range(line_idx, -1, -1):
        m = re.match(r'^func\s+(?:\([^)]*\)\s+)?(\w+)', lines[i])
        if m:
            return m.group(1)
    return '<unknown>'

for root, dirs, files in os.walk('/bench/repo'):
    # skip proto and vendor
    if 'proto/gen' in root or 'vendor' in root or '.git' in root:
        continue
    for f in files:
        if not f.endswith('.go'):
            continue
        path = os.path.join(root, f)
        try:
            with open(path) as fh:
                content = fh.read()
                lines = content.splitlines()
        except:
            continue

        for idx, line in enumerate(lines):
            # skip definition
            if re.match(r'^func\s+\([^)]*\*Store\)\s+GetUser\s*\(', line.strip()):
                continue
            if re.match(r'^func\s+\([^)]*\*DB\)\s+GetUser\s*\(', line.strip()):
                continue

            is_call = False
            if call_pattern.search(line):
                is_call = True
            elif '/store/' in path and store_pkg_pattern.search(line):
                is_call = True

            if is_call:
                func = find_func_name(lines, idx)
                results.append((path, idx+1, line.strip(), func))

# dedupe by (path, func) for caller list
callers = {}
for path, line, content, func in results:
    key = (func, path)
    if key not in callers:
        callers[key] = []
    callers[key].append((line, content))

print("=== DEFINITION ===")
for root, dirs, files in os.walk('/bench/repo/store'):
    for f in files:
        if f.endswith('.go'):
            path = os.path.join(root, f)
            with open(path) as fh:
                for idx, line in enumerate(fh, 1):
                    if re.match(r'^func\s+\([^)]*\*Store\)\s+GetUser\s*\(', line.strip()):
                        print(f"Store.GetUser — {path}:{idx}")

print("\n=== CALLERS (unique func — file) ===")
for (func, path), sites in sorted(callers.items(), key=lambda x: (x[0][1], x[0][0])):
    test_marker = " [TEST]" if '_test.go' in path or '/test/' in path else ""
    print(f"{func} — {path}{test_marker} ({len(sites)} call site(s))")

print(f"\nTotal unique callers: {len(callers)}")
print(f"Total call sites: {sum(len(v) for v in callers.values())}")
